const webhookData = $('Webhook').item.json;
const headers = webhookData.headers || {};
const tenantId = headers['x-tenant-id'] || '00000000-0000-0000-0000-000000000001';
const documentId = headers['x-document-id'] || '';
const fileName = $binary.file.fileName || 'document.pdf';
const storagePath = `${tenantId}/${documentId}_${fileName}`;
const publicUrl = `https://mvbynpfvxcpvuoazkaxc.supabase.co/storage/v1/object/public/documents/${storagePath}`;

return [{
  json: {
    documentId,
    tenantId,
    fileName,
    storagePath,
    publicUrl,
    timestamp: new Date().toISOString()
  }
}];

const metadata = $('Extract Metadata').item.json;
const versionResult = $('Save Version').item.json;

return [{
  json: {
    success: true,
    documentId: metadata.documentId,
    tenantId: metadata.tenantId,
    filename: metadata.fileName,
    fileUrl: metadata.publicUrl,
    storageProvider: 'supabase',
    version: versionResult ? versionResult.version_number : 1,
    versionId: versionResult ? versionResult.id : null,
    storagePath: metadata.storagePath,
    timestamp: new Date().toISOString(),
    message: 'Archivo subido a Supabase Storage y version registrada'
  }
}];
